function teamNames(){const translated={'en-CA':{food:['TEAM APPLE','TEAM ICE TEA'],tech:['TEAM TV','TEAM MICROWAVE']},'fr-CA':{food:['ÉQUIPE POMME','ÉQUIPE THÉ GLACÉ'],tech:['ÉQUIPE TÉLÉ','ÉQUIPE MICRO-ONDES']},'fr-FR':{food:['ÉQUIPE POMME','ÉQUIPE THÉ GLACÉ'],tech:['ÉQUIPE TÉLÉ','ÉQUIPE MICRO-ONDES']},'es-ES':{food:['EQUIPO MANZANA','EQUIPO TÉ HELADO'],tech:['EQUIPO TV','EQUIPO MICROONDAS']},'de-DE':{food:['TEAM APFEL','TEAM EISTEE'],tech:['TEAM TV','TEAM MIKROWELLE']},'it-IT':{food:['SQUADRA MELA','SQUADRA TÈ FREDDO'],tech:['SQUADRA TV','SQUADRA MICROONDE']},'pt-PT':{food:['EQUIPA MAÇÃ','EQUIPA CHÁ GELADO'],tech:['EQUIPA TV','EQUIPA MICRO-ONDAS']},'nl-NL':{food:['TEAM APPEL','TEAM IJSTHEE'],tech:['TEAM TV','TEAM MAGNETRON']},'pl-PL':{food:['DRUŻYNA JABŁKO','DRUŻYNA MROŻONA HERBATA'],tech:['DRUŻYNA TV','DRUŻYNA MIKROFALA']},'ja-JP':{food:['チームアップル','チームアイスティー'],tech:['チームテレビ','チーム電子レンジ']},'zh-CN':{food:['苹果队','冰茶队'],tech:['电视队','微波炉队']}};const names=translated[selectedLanguage]||translated['en-CA'];return names[settings.store==='food'?'food':'tech']}
function teamIconFor(team){if(battleMode!=='team')return '';const [first,second]=teamNames();if(settings.store==='food')return team===first?'🍎':'🧊';return team===first?'📺':'🍽️'}
function assignTeams(){if(battleMode!=='team')return;const [first,second]=teamNames(),palette=['orange','blue','green','yellow','pink','black'];if(!settings.opponentOutfit||settings.opponentOutfit===settings.avatar)settings.opponentOutfit=palette.find(color=>color!==settings.avatar&&color!==settings.opponentOutfit)||'blue';comPlayers.forEach((bot,index)=>{bot.team=index<2?first:second;bot.outfit=index<2?settings.avatar:settings.opponentOutfit});settings.team=first}
function isTeamMatch(){return playMode==='com'&&battleMode==='team'}
function activeBasket(){return isTeamMatch()?teamBasket:cart}
function randomizeComPlayers(){const names=['BYTE BOT','NOVA COM','PIXEL AI','GEAR UNIT','ORBIT BOT'];const outfits=['orange','blue','green','yellow','pink'];const spots=[[18,62],[33,48],[50,57],[68,43],[83,60]];comPlayers=names.map((name,i)=>({name,outfit:outfits[(i+Math.floor(Math.random()*outfits.length))%outfits.length],score:0,budget:startingBudget(),x:spots[i][0],y:spots[i][1],target:null,taken:0,team:null,phase:'shopping',finished:false,checkoutStage:0}));assignTeams();renderRoster()}
function renderRoster(){if(playMode!=='com'){roster.hidden=true;return}assignTeams();roster.hidden=false;const human=settings.name||'YOU';if(battleMode==='team'){const [first,second]=teamNames();const icon=settings.store==='food'?['🍎','🧊']:['📺','🍽️'];const card=(name,color,isHuman=false)=>`<div class="team-card ${isHuman?'human':''}">${isHuman?'':`<i class="robot">🤖</i>`}<i class="player-circle" style="--member-color:${color}"></i>${name}</div>`;roster.className='setup-team-strip';roster.innerHTML=`<aside class="team-edge apple"><div><span class="team-icon">${icon[0]}</span>${first}</div></aside><div class="team-roster">${card(human,outfitColor(settings.avatar),true)}${comPlayers.map(p=>card(p.name,outfitColor(p.outfit))).join('')}</div><aside class="team-edge ice"><div><span class="team-icon">${icon[1]}</span>${second}</div></aside>`;return}roster.className='com-roster';roster.innerHTML=`<span class="roster-player human"><i class="dot" style="--outfit:${outfitColor(settings.avatar)}"></i>${human}</span>`+comPlayers.map(p=>`<span class="roster-player"><i class="bot">🤖</i><i class="dot" style="--outfit:${outfitColor(p.outfit)}"></i>${p.name}</span>`).join('')}
function outfitColor(outfit){return({orange:'#ff7c57',blue:'#559de4',green:'#52bb82',yellow:'#e6bd3f',pink:'#e46fa7',black:'#536074'})[outfit]||'#ff7c57'}
function renderTeamHud(){teamHud.innerHTML=''}
function renderComPlayers(){if(playMode!=='com'){comArea.innerHTML='';return}comArea.innerHTML=comPlayers.map(p=>`<div class="com-shopper ${p.outfit} ${p.team===settings.team?'ally':'rival'} ${p.finished?'finished':''}" style="left:${p.x}%;top:${p.y}%"><div class="character3d shopper3d outfit-${p.outfit}"><div class="hair3d"></div><div class="head3d"><i></i><i></i><b></b></div><div class="torso3d"></div><div class="arm3d left-arm"></div><div class="arm3d right-arm"></div><div class="leg3d left-leg"></div><div class="leg3d right-leg"></div><em>🛒${p.taken||''}</em></div><span class="com-name">${teamIconFor(p.team)?`<i class="name-team-icon">${teamIconFor(p.team)}</i>`:''}🤖 ${p.name}</span></div>`).join('')}
function affordableProducts(budget){return groceries.map((g,i)=>({g,i})).filter(({g})=>g.stock>0&&budget>=currencyAmount(g.price))}
function checkoutApproachPoint(index=0){const store=$('#game .store').getBoundingClientRect(),register=$('#checkout .register').getBoundingClientRect(),baseX=(register.left-store.left-32)/store.width*100,baseY=(register.top-store.top-38)/store.height*100;return{x:Math.max(7,Math.min(88,baseX)),y:Math.max(16,Math.min(76,baseY-index*2.4))}}
function botCheckoutWaypoint(bot,index){const checkoutPoint=checkoutApproachPoint(index);if(settings.store!=='tech')return checkoutPoint;if(!Number.isInteger(bot.checkoutStage))bot.checkoutStage=0;if(bot.checkoutStage===0){const waypoint={x:bot.x<48?42:87,y:32};if(Math.hypot(waypoint.x-bot.x,waypoint.y-bot.y)<2.5)bot.checkoutStage=1;return waypoint}if(bot.checkoutStage===1){const waypoint={x:87,y:32};if(Math.hypot(waypoint.x-bot.x,waypoint.y-bot.y)<2.5){bot.checkoutStage=2;return checkoutPoint}return waypoint}return checkoutPoint}
function clampShopperPosition(x,y){return{x:Math.max(7,Math.min(88,x)),y:Math.max(16,Math.min(76,y))}}
// Shelves are depth scenery rather than invisible walls: shoppers may cross to
// the rear aisle, but the furniture will visually cover them while they do.
function canShopperMoveTo(x,y){return!blockedByCheckout(x,y)}
function botStep(bot,target){const dx=target.x-bot.x,dy=target.y-bot.y,sx=Math.sign(dx)*Math.min(1.2,Math.abs(dx)),sy=Math.sign(dy)*Math.min(.9,Math.abs(dy)),sideX=Math.sign(dy||1)*.9,sideY=-Math.sign(dx||1)*.7,candidates=[[sx,sy],[sx,0],[0,sy],[sideX,sideY],[-sideX,-sideY],[sideX,0],[-sideX,0],[0,sideY],[0,-sideY]];for(const [moveX,moveY] of candidates){const next=clampShopperPosition(bot.x+moveX,bot.y+moveY);if(canShopperMoveTo(next.x,next.y)){bot.x=next.x;bot.y=next.y;return true}}return false}
function updateBotNode(bot,index,moving=false){const node=comArea.children[index];if(!node)return;const shelf=occludingShelf(bot.x,bot.y,.78,92);node.style.left=bot.x+'%';node.style.top=bot.y+'%';node.classList.toggle('moving',moving&&!bot.finished);node.classList.toggle('finished',Boolean(bot.finished));node.classList.toggle('behind-shelf',Boolean(shelf));applyShelfMask(node,shelf);node.querySelector('.character3d')?.classList.toggle('walking',moving&&!bot.finished);node.querySelector('em').textContent='🛒'+(bot.taken||'')}
function maybeEndDepletedMatch(){if(playMode!=='com'||tutorialActive||!active||countdownActive||shoppingEndQueued)return;const budgets=[playerBudget,...comPlayers.filter(bot=>!bot.finished).map(bot=>bot.budget)],canShop=groceries.some(item=>item.stock>0&&budgets.some(budget=>budget>=currencyAmount(item.price)));if(canShop)return;shoppingEndQueued=true;const finish=()=>{if(!active)return;if(paused){setTimeout(finish,250);return}checkout(true,'stock')};setTimeout(finish,500)}
function startBots(){clearInterval(botTimer);if(playMode!=='com')return;botTimer=setInterval(()=>{if(!active||paused||countdownActive)return;comPlayers.forEach((bot,index)=>{if(bot.finished){updateBotNode(bot,index);return}if(bot.phase==='checkout'){const checkoutPoint=checkoutApproachPoint(index),waypoint=botCheckoutWaypoint(bot,index),moving=botStep(bot,waypoint);if(Math.hypot(checkoutPoint.x-bot.x,checkoutPoint.y-bot.y)<4){bot.finished=true;bot.phase='finished'}updateBotNode(bot,index,moving);return}let target=groceries[bot.target],available=affordableProducts(bot.budget);if(!available.length||seconds<=30){bot.phase='checkout';bot.target=null;updateBotNode(bot,index);return}if(!target||target.stock<=0||bot.budget<currencyAmount(target.price)){const choice=available[Math.floor(Math.random()*available.length)];bot.target=choice.i;target=choice.g}const moving=botStep(bot,target);if(itemDistance(bot.x,bot.y,target)<pickupRange()){const cost=currencyAmount(target.price);if(target.stock>0&&bot.budget>=cost){target.stock--;bot.budget-=cost;bot.score+=target.price;bot.taken++;if(isTeamMatch()&&bot.team===settings.team)teamBasket.push({...target,owner:bot.name});update();draw()}bot.target=null}updateBotNode(bot,index,moving)});maybeEndDepletedMatch()},120)}
