function tutorialTasks(){return isMobileDevice()?mobileText().tutorial:(tutorialTasksByLanguage[selectedLanguage]||tutorialTasksByLanguage['en-CA'])}
function renderTutorial(){if(!tutorialActive){tutorialPanel.hidden=true;return}const tasks=tutorialTasks(),task=tasks[tutorialStep]||tasks[tasks.length-1],exerciseName=({'fr-CA':'EXERCICE','fr-FR':'EXERCICE','es-ES':'EJERCICIO','de-DE':'ÜBUNG','it-IT':'ESERCIZIO','pt-PT':'EXERCÍCIO','nl-NL':'OEFENING','pl-PL':'ĆWICZENIE','ja-JP':'エクササイズ','zh-CN':'练习'})[selectedLanguage]||'EXERCISE',taskText=task[1].replaceAll('<kbd>E</kbd>','<kbd>C</kbd>');tutorialPanel.hidden=false;tutorialPanel.innerHTML=`<div class="tutorial-step">${exerciseName} ${Math.min(tutorialStep+1,tasks.length)} / ${tasks.length}</div><div class="tutorial-task"><b>${task[0]}:</b> ${taskText}</div><div class="tutorial-progress"><i style="width:${(tutorialStep/tasks.length)*100}%"></i></div>`}
function advanceTutorial(){const tasks=tutorialTasks();if(!tutorialActive)return;tutorialStep++;if(tutorialStep>=tasks.length){tutorialStep=tasks.length-1;return}renderTutorial()}
function startTutorial(){playMode='solo';battleMode='ffa';tutorialActive=true;tutorialStep=0;settings.store='food';settings.currency='usd';settings.name=settings.name||'ROOKIE';launch()}
function showTutorialComplete(){changeScreen('tutorial-complete')}
function openModeSelect(){playMode='com';changeScreen('mode-select');modeScreen.classList.add('active')}
function toReady(){updateReady();renderRoster();changeScreen('ready')}
function makeItems(){groceries=stores[settings.store].items.map(([name,price,icon,color,x,y,stock=3],index)=>({id:`${settings.store}-${index}`,name,price,icon,color,x,y,stock,maxStock:stock}))}
function draw(){const area=$('#items');area.innerHTML='';groceries.forEach((g,i)=>{const soldOut=g.stock<=0,e=document.createElement('button');e.className=`item ${soldOut?'sold-out':''}`;e.disabled=soldOut;e.dataset.index=i;const perspectiveScale=.64+g.y/130,scale=settings.store==='tech'?perspectiveScale*.68:perspectiveScale;e.style.cssText=`left:${g.x}%;top:${g.y}%;--color:${g.color};--item-scale:${scale};z-index:${Math.round(g.y*10)}`;e.innerHTML=`<span class="item-meta"><b class="stock-count">${soldOut?`0 ${gameplayText('left')}`:`${g.stock} ${gameplayText('left')}`}</b><b class="price">${soldOut?gameplayText('soldOut'):format(g.price)}</b></span><span class="box" data-icon="${g.icon}" data-sold-out="${gameplayText('soldOut')}"></span><small>${productName(g.name)}</small>`;e.onclick=()=>tryTake(i);area.append(e)});updateTakePrompt()}
function update(){const basket=activeBasket(),sum=basket.reduce((a,g)=>a+g.price,0);$('#total').textContent=format(sum);$('#regtotal').textContent=format(sum);$('#pause-total').textContent=format(sum);$('#budget').textContent=formatBudget(playerBudget);$('#cart').innerHTML=basket.length?basket.map(g=>`<span class="chip">${g.icon} ${productName(g.name)}</span>`).join(''):emptyBasketText();$('#player em').textContent=basket.length?`🛒${basket.length}`:'🛒'}
function pickupRange(){return settings.store==='tech'?18:8}
function itemDistance(x,y,item){return Math.hypot((item.x-x)*.78,item.y-y)}
function nearestItem(){let match=null,best=Infinity;groceries.forEach((g,i)=>{if(g.stock<=0)return;const d=itemDistance(playerX,playerY,g);if(d<best){best=d;match={g,i,d}}});return match}
function nearCheckout(){const player=$('#player').getBoundingClientRect(),checkoutZone=$('#checkout').getBoundingClientRect(),playerCenter={x:player.left+player.width/2,y:player.top+player.height/2},checkoutCenter={x:checkoutZone.left+checkoutZone.width/2,y:checkoutZone.top+checkoutZone.height/2};return Math.hypot(playerCenter.x-checkoutCenter.x,playerCenter.y-checkoutCenter.y)<150}
function updateTakePrompt(){const near=nearestItem();$$('.item').forEach(e=>e.classList.remove('near'));if(near&&near.d<pickupRange())$(`.item[data-index="${near.i}"]`)?.classList.add('near');$('.instructions').hidden=true}
function showBudgetHint(){const hint=$('.instructions');clearTimeout(showBudgetHint.timer);hint.textContent=budgetHintTranslations[selectedLanguage]||budgetHintTranslations['en-CA'];hint.hidden=false;showBudgetHint.timer=setTimeout(()=>hint.hidden=true,2600)}
function tryTake(index){const near=nearestItem();if(index!==undefined&&(!near||near.i!==index))return;if(!near||near.d>=pickupRange()||!active||paused||countdownActive)return;const g=near.g;if(playMode==='multiplayer'){window.RapidoMultiplayer?.takeProduct(g.id);return}const cost=currencyAmount(g.price);if(playerBudget<cost){showBudgetHint();return}playerBudget-=cost;g.stock--;const item={...g,owner:settings.name};cart.push(item);if(isTeamMatch())teamBasket.push(item);if(tutorialActive&&tutorialStep===4)advanceTutorial();update();draw();maybeEndDepletedMatch()}
function updatePlayer(walking=false){const player=$('#player'),scale=.58+playerY/110,shelf=occludingShelf(playerX,playerY,scale),behindShelf=Boolean(shelf);player.style.left=playerX+'%';player.style.top=playerY+'%';player.style.bottom='auto';player.style.zIndex=behindShelf?1:Math.round(playerY*10);player.style.transform=`scale(${scale})`;player.classList.toggle('behind-shelf',behindShelf);applyShelfMask(player,shelf);player.classList.toggle('walking',walking);updateTakePrompt();if(playMode==='multiplayer')window.RapidoMultiplayer?.onLocalMove(playerX,playerY,walking)}
function refreshLeaderboard(){const board=$('.board'),name=settings.name||'YOU',playerScore=cart.reduce((total,item)=>total+item.price,0);if(playMode==='com'){const rows=[{name,score:playerScore,human:true},...comPlayers].sort((a,b)=>b.score-a.score);board.innerHTML=rows.map(p=>`${p.human?'':'<span class="bot">🤖</span>'}${p.name} <b>${format(p.score)}</b>`).join('<br>')}else board.innerHTML=`${name} <b>${format(playerScore)}</b><br>CASA CART <b>${format(18.75)}</b><br>QUICK MARTY <b>${format(13.2)}</b>`}
